add_task(function testSender() {
  function test(from, expectedSender, charset) {
    const message = folder.addMessage(
      generator
        .makeMessage({
          from,
          clobberHeaders: { "Content-type": `text/plain; charset=${charset}` },
        })
        .toMessageString()
    );
    Assert.equal(
      message.author,
      expectedSender,
      "author should be decoded and normalised"
    );
